toolArgs.file_text:
@page "/board"
@rendermode InteractiveServer
@using sv_248741df625640a4824674a52a2c62dc
@using sv_248741df625640a4824674a52a2c62dc.Components.Pages.Board
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Project Board</h2>

@if (isLoading)
{
    <p class="loading-message">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <div class="error-message">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar TotalCount="allTasks.Count"
                   ToDoCount="GetTasksForStatus("To Do").Count"
                   InProgressCount="GetTasksForStatus("In Progress").Count"
                   DoneCount="GetTasksForStatus("Done").Count"
                   OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar SearchTerm="@searchTerm" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        @for (int i = 0; i < columns.Length; i++)
        {
            var colIndex = i;
            var status = columns[colIndex];
            <KanbanColumn ColumnName="@status"
                          Tasks="GetFilteredTasksForStatus(status)"
                          CanMoveLeft="colIndex > 0"
                          CanMoveRight="colIndex < columns.Length - 1"
                          IsMoving="isMoving"
                          IsAdding="isAdding"
                          OnMoveLeft="(taskId) => MoveTask(taskId, columns[colIndex - 1])"
                          OnMoveRight="(taskId) => MoveTask(taskId, columns[colIndex + 1])"
                          OnTaskCreated="(form) => CreateTask(form, status)" />
        }
    </div>
}

@code {
    private static readonly string[] columns = { "To Do", "In Progress", "Done" };

    private List<TaskItem> allTasks = new();
    private string searchTerm = string.Empty;
    private bool isLoading = true;
    private bool isMoving;
    private bool isAdding;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleSearchChanged(string term)
    {
        searchTerm = term;
    }

    private List<TaskItem> GetTasksForStatus(string status) =>
        allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksForStatus(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            isMoving = true;
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            allTasks[allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
        finally
        {
            isMoving = false;
        }
    }

    private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) form, string status)
    {
        try
        {
            isAdding = true;
            var newTask = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            isAdding = false;
        }
    }
}

